`timescale 1ns/1ps
// T4 lockstep equivalence bench (docs/decisions/T4_LOOKAHEAD_CONTRACT.md sec. 3).
// For each of the 6 mesh coordinates: the original noc_router (protected RTL) and noc_router_t4eq (the T4 lookahead variant,
// equivalence copy generated by scripts/prepare_t4.py) receive the same stimulus; every output (5 flit / valid pairs,
// in_ready_local, credit_out) is compared bit for bit every cycle.
// Stimulus: XY-legal wormhole traffic (no U-turns) on every existing mesh input, credit-respecting (VC depth 4), all 3 VCs,
// HEAD / BODY / TAIL / HEAD_TAIL, random payload (header bits included on BODY flits); LOCAL input with the ready handshake,
// destinations incl. off-mesh (route_valid = 0); downstream credits returned after random delays; random out_ready_local;
// reset every 5,000 cycles (clears off-mesh-stuck VCs, exercises reset). 20,000 cycles per coordinate.
// CHECKS = 12: EQ_<n>_OUTPUTS (zero mismatches) and EQ_<n>_TRAFFIC (>= 2,000 flits delivered, every existing output used).
module t4_env #(parameter int X = 0, parameter int Y = 0, parameter int unsigned SEED = 1) (
  input  logic clk,
  output int   mism, output int delivered, output logic [4:0] used, output logic [4:0] exists, output logic done);
  import noc_pkg::*;
  localparam int CYCLES = 20000;
  localparam int DEPTH = 4;
  logic rst;
  coord_t cc;
  assign cc.x = X[COORD_WIDTH-1:0];
  assign cc.y = Y[COORD_WIDTH-1:0];

  flit_t inf [NUM_PORTS];
  logic  inv [NUM_PORTS];
  logic [NUM_VC-1:0] cret [NUM_PORTS];
  logic [NUM_VC-1:0] co_r [NUM_PORTS], co_d [NUM_PORTS];
  flit_t of_r [NUM_PORTS], of_d [NUM_PORTS];
  logic  ov_r [NUM_PORTS], ov_d [NUM_PORTS];
  logic  rdy_r, rdy_d, ordy;

  noc_router u_ref (.clk, .rst, .current_coord(cc),
    .in_flit_north(inf[PORT_NORTH]), .in_valid_north(inv[PORT_NORTH]), .in_flit_south(inf[PORT_SOUTH]), .in_valid_south(inv[PORT_SOUTH]),
    .in_flit_east (inf[PORT_EAST]),  .in_valid_east (inv[PORT_EAST]),  .in_flit_west (inf[PORT_WEST]),  .in_valid_west (inv[PORT_WEST]),
    .in_flit_local(inf[PORT_LOCAL]), .in_valid_local(inv[PORT_LOCAL]), .in_ready_local(rdy_r),
    .credit_return(cret), .credit_out(co_r),
    .out_flit_north(of_r[PORT_NORTH]), .out_valid_north(ov_r[PORT_NORTH]), .out_flit_south(of_r[PORT_SOUTH]), .out_valid_south(ov_r[PORT_SOUTH]),
    .out_flit_east (of_r[PORT_EAST]),  .out_valid_east (ov_r[PORT_EAST]),  .out_flit_west (of_r[PORT_WEST]),  .out_valid_west (ov_r[PORT_WEST]),
    .out_flit_local(of_r[PORT_LOCAL]), .out_valid_local(ov_r[PORT_LOCAL]), .out_ready_local(ordy));
  noc_router_t4eq u_dut (.clk, .rst, .current_coord(cc),
    .in_flit_north(inf[PORT_NORTH]), .in_valid_north(inv[PORT_NORTH]), .in_flit_south(inf[PORT_SOUTH]), .in_valid_south(inv[PORT_SOUTH]),
    .in_flit_east (inf[PORT_EAST]),  .in_valid_east (inv[PORT_EAST]),  .in_flit_west (inf[PORT_WEST]),  .in_valid_west (inv[PORT_WEST]),
    .in_flit_local(inf[PORT_LOCAL]), .in_valid_local(inv[PORT_LOCAL]), .in_ready_local(rdy_d),
    .credit_return(cret), .credit_out(co_d),
    .out_flit_north(of_d[PORT_NORTH]), .out_valid_north(ov_d[PORT_NORTH]), .out_flit_south(of_d[PORT_SOUTH]), .out_valid_south(ov_d[PORT_SOUTH]),
    .out_flit_east (of_d[PORT_EAST]),  .out_valid_east (ov_d[PORT_EAST]),  .out_flit_west (of_d[PORT_WEST]),  .out_valid_west (ov_d[PORT_WEST]),
    .out_flit_local(of_d[PORT_LOCAL]), .out_valid_local(ov_d[PORT_LOCAL]), .out_ready_local(ordy));

  // sender / receiver state
  int credit [NUM_PORTS][NUM_VC];
  int pend   [NUM_PORTS][NUM_VC];
  bit active [NUM_PORTS][NUM_VC];
  int bodies [NUM_PORTS][NUM_VC];
  bit lhold; int lvc;
  logic [NUM_VC-1:0] co_q [NUM_PORTS];
  logic local_acc, ov_q [NUM_PORTS], ordy_q;
  flit_t of_q [NUM_PORTS];

  // samples taken AT the clock edge (pre-edge values): credits to us, flits leaving, LOCAL acceptance
  always @(posedge clk) begin
    co_q <= co_r; ov_q <= ov_r; of_q <= of_r; ordy_q <= ordy;
    local_acc <= inv[PORT_LOCAL] && rdy_r;
  end

  function automatic coord_t legal_dest(int p);
    coord_t d; int k;
    for (k = 0; k < 64; k++) begin
      d.x = $urandom_range(MESH_X-1); d.y = $urandom_range(MESH_Y-1);
      case (p)
        PORT_WEST:  if (d.x >= X) return d;                   // came from the west, travelling east
        PORT_EAST:  if (d.x <= X) return d;
        PORT_NORTH: if (d.x == X && d.y >= Y) return d;       // came from the north, travelling south
        PORT_SOUTH: if (d.x == X && d.y <= Y) return d;
        default: begin
          if ($urandom_range(99) < 3) begin d.x = $urandom_range(7); d.y = MESH_Y + $urandom_range(7 - MESH_Y); return d; end
          if (d.x != X || d.y != Y) return d;                  // no LOCAL -> LOCAL loopback
        end
      endcase
    end
    d.x = X; d.y = Y; return d;
  endfunction

  function automatic flit_t next_flit(int p, int v);
    flit_t f; coord_t d;
    f.flit_data = $urandom(); f.vc_id = v;
    if (!active[p][v]) begin
      d = legal_dest(p);
      f.flit_data[31:29] = d.x; f.flit_data[28:26] = d.y;
      bodies[p][v] = $urandom_range(3);
      if (bodies[p][v] == 0 && $urandom_range(1)) f.flit_type = FLIT_HEAD_TAIL;
      else begin f.flit_type = FLIT_HEAD; active[p][v] = 1; end
    end else if (bodies[p][v] > 0) begin f.flit_type = FLIT_BODY; bodies[p][v]--; end
    else begin f.flit_type = FLIT_TAIL; active[p][v] = 0; end
    return f;
  endfunction

  task automatic clear_env();
    for (int p = 0; p < NUM_PORTS; p++) begin
      inv[p] = 0; inf[p] = '0; cret[p] = '0;
      for (int v = 0; v < NUM_VC; v++) begin credit[p][v] = DEPTH; pend[p][v] = 0; active[p][v] = 0; bodies[p][v] = 0; end
    end
    lhold = 0; ordy = 0;
  endtask

  initial begin
    automatic int cyc = 0;
    void'($urandom(SEED));
    mism = 0; delivered = 0; used = '0; done = 0;
    for (int p = 0; p < NUM_PORTS; p++) exists[p] = (p == PORT_LOCAL) ? 1'b1 : port_exists(cc, port_e'(p));
    clear_env(); rst = 1;
    repeat (5) @(negedge clk);
    rst = 0;
    while (cyc < CYCLES) begin
      @(negedge clk); cyc++;
      // compare everything, every cycle
      if (rdy_r !== rdy_d) mism++;
      for (int p = 0; p < NUM_PORTS; p++)
        if (of_r[p] !== of_d[p] || ov_r[p] !== ov_d[p] || co_r[p] !== co_d[p]) mism++;
      if (cyc % 5000 == 0) begin   // periodic reset
        clear_env(); rst = 1; repeat (3) @(negedge clk); rst = 0; continue;
      end
      // account the edge that just happened
      for (int p = 0; p < NUM_PORTS; p++) begin
        if (p != PORT_LOCAL) for (int v = 0; v < NUM_VC; v++) if (co_q[p][v]) credit[p][v]++;
        if (ov_q[p] && (p != PORT_LOCAL || ordy_q)) begin
          delivered++; used[p] = 1'b1;
          if (p != PORT_LOCAL) pend[p][of_q[p].vc_id]++;
        end
      end
      if (local_acc) lhold = 0;
      // downstream credit returns (random delay)
      for (int p = 0; p < NUM_PORTS; p++) begin
        cret[p] = '0;
        if (p != PORT_LOCAL) for (int v = 0; v < NUM_VC; v++)
          if (pend[p][v] > 0 && $urandom_range(2) != 0) begin cret[p][v] = 1'b1; pend[p][v]--; end
      end
      ordy = ($urandom_range(3) != 0);
      // mesh senders: at most one flit per input port per cycle, on a VC with credit
      for (int p = 0; p < NUM_PORTS; p++) begin
        if (p == PORT_LOCAL) continue;
        inv[p] = 0;
        if (!exists[p] || $urandom_range(3) == 0) continue;
        begin
          automatic int v0 = $urandom_range(NUM_VC-1);
          for (int k = 0; k < NUM_VC; k++) begin
            automatic int v = (v0 + k) % NUM_VC;
            if (credit[p][v] > 0 && (active[p][v] || $urandom_range(2) == 0)) begin
              inf[p] = next_flit(p, v); inv[p] = 1; credit[p][v]--; break;
            end
          end
        end
      end
      // LOCAL sender: hold the flit until accepted
      if (!lhold) begin
        inv[PORT_LOCAL] = 0;
        if ($urandom_range(2) != 0) begin
          lvc = $urandom_range(NUM_VC-1);
          for (int k = 0; k < NUM_VC; k++) if (active[PORT_LOCAL][(lvc + k) % NUM_VC]) begin lvc = (lvc + k) % NUM_VC; break; end
          inf[PORT_LOCAL] = next_flit(PORT_LOCAL, lvc); inv[PORT_LOCAL] = 1; lhold = 1;
        end
      end
    end
    done = 1;
  end
endmodule

module tb_t4_router_equiv;
  logic clk = 0;
  always #5 clk = ~clk;
  int mism [6], delivered [6];
  logic [4:0] used [6], exists [6];
  logic done [6];
  t4_env #(.X(0), .Y(0), .SEED(101)) e0 (.clk, .mism(mism[0]), .delivered(delivered[0]), .used(used[0]), .exists(exists[0]), .done(done[0]));
  t4_env #(.X(1), .Y(0), .SEED(202)) e1 (.clk, .mism(mism[1]), .delivered(delivered[1]), .used(used[1]), .exists(exists[1]), .done(done[1]));
  t4_env #(.X(2), .Y(0), .SEED(303)) e2 (.clk, .mism(mism[2]), .delivered(delivered[2]), .used(used[2]), .exists(exists[2]), .done(done[2]));
  t4_env #(.X(0), .Y(1), .SEED(404)) e3 (.clk, .mism(mism[3]), .delivered(delivered[3]), .used(used[3]), .exists(exists[3]), .done(done[3]));
  t4_env #(.X(1), .Y(1), .SEED(505)) e4 (.clk, .mism(mism[4]), .delivered(delivered[4]), .used(used[4]), .exists(exists[4]), .done(done[4]));
  t4_env #(.X(2), .Y(1), .SEED(606)) e5 (.clk, .mism(mism[5]), .delivered(delivered[5]), .used(used[5]), .exists(exists[5]), .done(done[5]));
  int checks = 0, errors = 0;
  task automatic check(input bit ok, input string name);
    checks++;
    if (ok) $display("[PASS] %s", name); else begin errors++; $display("[FAIL] %s", name); end
  endtask
  initial begin
    $display("CONFIG: TOP=tb_t4_router_equiv CHECKS=12 CYCLES_PER_COORD=20000");
    wait (done[0] && done[1] && done[2] && done[3] && done[4] && done[5]);
    for (int n = 0; n < 6; n++) begin
      check(mism[n] == 0, $sformatf("EQ_%0d_OUTPUTS mismatches=%0d", n, mism[n]));
      check(delivered[n] >= 2000 && used[n] == exists[n],
            $sformatf("EQ_%0d_TRAFFIC delivered=%0d used=%b exists=%b", n, delivered[n], used[n], exists[n]));
    end
    $display("CHECKS : %0d", checks);
    $display("ERRORS : %0d", errors);
    $display("RESULT : %s", errors == 0 && checks == 12 ? "PASS" : "FAIL");
    $finish;
  end
  initial begin #5ms; $display("TB_TIMEOUT global"); $finish; end
endmodule
